package com.casystem.onboarding.controller;
import com.casystem.onboarding.model.AuditLog;import com.casystem.onboarding.repository.*;import com.casystem.onboarding.service.TokenService;import org.junit.jupiter.api.*;import org.mockito.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LocationAuditControllerTest{@Test void locationLocalYValidaciones(){PostalCodeRepository p=mock(PostalCodeRepository.class);LocationController c=new LocationController(p);assertEquals(32,c.states().size());when(p.municipalities("Veracruz")).thenReturn(List.of("Veracruz"));assertEquals(List.of("Veracruz"),c.municipalities("Veracruz"));when(p.find("91810")).thenReturn(List.of(Map.of("state","Veracruz","municipality","Veracruz","settlement","Playa Linda"),Map.of("state","Veracruz","municipality","Veracruz","settlement","Playa Linda")));var r=c.postalCode("91810");assertEquals(true,r.get("found"));assertEquals(1,((List<?>)r.get("settlements")).size());assertThrows(IllegalArgumentException.class,()->c.postalCode("9180"));}
@Test void auditoriaUsuario(){AuditLogRepository repo=mock(AuditLogRepository.class);TokenService t=mock(TokenService.class);when(t.userId("h")).thenReturn(5L);AuditLog a=new AuditLog();when(repo.findByUserIdOrderByCreatedAtDesc(5L)).thenReturn(List.of(a));assertEquals(1,new AuditController(repo,t).mine("h").size());}}
